import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
	public static void main (String[] args) throws java.lang.Exception
	{
		// your code goes here
		Scanner sc = new Scanner(System.in);
		
		int t = sc.nextInt();
		
		while(t-- > 0){
		    
		    int n = sc.nextInt();
		    int m = 3*n;
		    
		    long[] a = new long[m];
		    
		    for(int i = 0; i<m; i++){
		        a[i] = sc.nextLong();
		    }
		    
		    Arrays.sort(a);
		    
		    long[] p = new long[m+1];
		    
		    for(int i = 0; i<m; i++){
		        p[i+1] = p[i]+a[m-1-i];
		    }
		    
		    long ans = 0;
		    for(int x = 0; x<=n; x++){
		        int l = 0;
		        int h = n-x;
		        
		        while(l<h){
		            int y = (l+h)/2;
		            
		            int q = x+2*y;
		            int r = 3*n-2*x-y;
		            
		            if(a[m-q-1] + a[m-q-2]>=3*a[m-r])
		                l = y+1;
		            else
		                h = y;
		            
		        }
		        ans = Math.max(ans, cal(a,p,n, x, l));
		        
		        if(l>0){
		            ans = Math.max(ans, cal(a, p, n, x, l-1));
		        }
		        
		        
		    }
		    System.out.println(ans);
		    
		}
		
		

	}
	
	static long cal(long[] a, long[] p, int n, int x, int y){
	    int q = x+2*y;
	    int r = 3*n-2*x-y;
	    
	    return 2*p[x]+p[q]+3*p[r];
	    
	}
	
	
	
}
